#!/usr/bin/env python3
"""Word-timed transcript of any clip, locally and free (faster-whisper).

Writes the same shape make_vo.py writes, so a film, lib/captions.js and
tools/subs.mjs all read it:  {duration, lines: [{i, text, start, end}], words: [{line, w, s, e}]}

    python tools/transcribe.py take.mp4                         # -> take.words.json
    python tools/transcribe.py take.mp4 --lang no --model medium
    python tools/transcribe.py take.mp4 --js brands/lab/films/take.words.js
    python tools/transcribe.py take.mp4 --fix fixes.txt --prompt "Claude, motionkit, Valorant"

--fix is one correction per line, `heard=meant` ("cloud=Claude"). ASR reliably
destroys exactly the names the audience is watching for; --prompt helps
whisper spell them, --fix catches what it still gets wrong.

No ffmpeg needed: faster-whisper decodes audio and video itself (PyAV).
Models download once to the Hugging Face cache (small ~460 MB).
"""

import argparse
import json
import os
import re
import sys


def load_fixes(path):
    """[(regex for the line text, heard words, meant)] from `heard=meant` lines."""
    out = []
    if not path:
        return out
    for raw in open(path, encoding='utf-8'):
        line = raw.strip()
        if not line or line.startswith('#') or '=' not in line:
            continue
        heard, meant = (p.strip() for p in line.split('=', 1))
        # whole words only, case-insensitive, keep the punctuation around it
        out.append((re.compile(rf'(?<![\w]){re.escape(heard)}(?![\w])', re.I), heard.lower().split(), meant))
    return out


def fix(text, fixes):
    for rx, _, meant in fixes:
        text = rx.sub(meant, text)
    return text


def bare(w):
    return re.sub(r'[^\w]+$', '', w.lower())


def fix_words(words, fixes):
    """The same fixes across word boundaries: "he frames" -> "Keyframes" is two
    words heard, one meant. Matched words merge into one that spans their
    times; the last word's punctuation is kept."""
    for _, heard, meant in fixes:
        n, i = len(heard), 0
        while i + n <= len(words):
            if [bare(w['w']) for w in words[i:i + n]] == heard:
                tail = re.search(r'[^\w]*$', words[i + n - 1]['w']).group(0)
                mw = meant.split()
                if len(mw) == n:   # same count: word for word, times kept
                    for k in range(n):
                        words[i + k]['w'] = mw[k] + (tail if k == n - 1 else '')
                else:
                    words[i:i + n] = [{**words[i], 'w': meant + tail, 'e': words[i + n - 1]['e']}]
                i += len(mw) if len(mw) == n else 1
            else:
                i += 1
    return words


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument('media')
    ap.add_argument('--out', help='words.json path (default: next to the media)')
    ap.add_argument('--js', help='also write a film module: export const VO = {...}')
    ap.add_argument('--lang', default=None, help='en, no, ... (default: detect)')
    ap.add_argument('--model', default='small', help='tiny | base | small | medium | large-v3')
    ap.add_argument('--fix', help='heard=meant corrections, one per line')
    ap.add_argument('--prompt', default=None, help='names and terms to bias spelling')
    ap.add_argument('--device', default='auto', help='auto | cpu | cuda')
    a = ap.parse_args()

    from faster_whisper import WhisperModel

    compute = 'int8' if a.device == 'cpu' else 'default'
    model = WhisperModel(a.model, device=a.device, compute_type=compute)
    segs, info = model.transcribe(a.media, language=a.lang, beam_size=5, word_timestamps=True,
                                  vad_filter=True, initial_prompt=a.prompt)
    fixes = load_fixes(a.fix)

    lines, words = [], []
    for seg in segs:
        ws = [w for w in (seg.words or []) if w.word.strip()]
        if not ws:
            continue
        i = len(lines)
        for w in ws:
            words.append({'line': i, 'w': w.word.strip(), 's': round(w.start, 3), 'e': round(w.end, 3)})
        lines.append({'i': i, 'text': fix(seg.text.strip(), fixes), 'start': round(ws[0].start, 3), 'end': round(ws[-1].end, 3)})
        print(f'{ws[0].start:7.2f}  {lines[-1]["text"]}', file=sys.stderr)

    words = fix_words(words, fixes)
    doc = {'duration': round(info.duration, 3), 'language': info.language, 'lines': lines, 'words': words}
    out = a.out or os.path.splitext(a.media)[0] + '.words.json'
    with open(out, 'w', encoding='utf-8') as f:
        json.dump(doc, f, ensure_ascii=False, indent=1)
    print(f'wrote {out}  ({len(words)} words, {len(lines)} lines, {info.language})')
    if a.js:
        with open(a.js, 'w', encoding='utf-8') as f:
            f.write(f'/* GENERATED by tools/transcribe.py from {os.path.basename(a.media)}: do not edit. */\n')
            f.write(f'export const VO = {json.dumps(doc, ensure_ascii=False)};\n')
        print(f'wrote {a.js}')


if __name__ == '__main__':
    main()
